





-- 105 entries, each a millisecond newer than the one before.
WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 105)
SELECT printf('01CX%022d', i), '01CS2300000000000000000000', 'material-added', printf('01CY%022d', i), printf('Apunte %03d', i), 1790000000000 + i
FROM n;
